/**
 * A paragraph of body text (`design/components/text.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/text.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, createDerived, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/text.module.css'

export type TextSize = NonNullable<TextProps['size']>

export type TextTone = NonNullable<TextProps['tone']>

export interface TextProps {
  children: JSX.Element
  /**
   * The most lines the paragraph draws; the last ends with an ellipsis. Only the drawing is cut,
   * so the whole text must be reachable another way (the page it opens, a detail view). A value
   * that is not a whole number reads as the whole number below it, and below 1 nothing is cut.
   */
  lines?: number
  size?: 'sm' | 'md'
  /**
   * Never below secondary; muted text is a caption, and captions belong to the components that
   * own them.
   */
  tone?: 'primary' | 'secondary'
}

/** A paragraph of body text. */
export default function Text(given: TextProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', tone: 'primary' } as Defaults<TextProps, 'size' | 'tone'>,
    claimSlot(given),
  )
  return scope(() => {
    const kept = createDerived(() => (props.lines === undefined ? 0 : Math.floor(props.lines)))
    const clamped = createDerived(() => kept.value >= 1)
    return (
      <p
        class={styles.text}
        style={{ '--pm-text-clamp': clamped.value ? kept.value : undefined }}
        data-size={props.size}
        data-tone={props.tone}
        data-lines={clamped.value ? kept.value : undefined}
        data-member="text"
      >
        {props.children}
      </p>
    )
  })
}
